-- An `ON CONFLICT DO UPDATE` that writes an oversized key is refused as an `UPDATE` is.
-- @setup
CREATE TABLE t (a text, b int);
CREATE INDEX t_a ON t (a);
CREATE UNIQUE INDEX t_b ON t (b);
INSERT INTO t VALUES ('x', 1);
-- @test
-- @expect-error: the update arm writes an oversized key
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('y', 1) ON CONFLICT (b) DO UPDATE SET a = '';
